using System;
using System.Collections.Generic;

using System.Web;
using System.Web.UI;
using System.Web.UI.WebControls;
using InformationWebObject;

namespace InformationWeb
{
    public partial class Dashboard : System.Web.UI.MasterPage
    {
        // Event này sẽ được chạy trước Page_Load của các control (nên dùng đúng hơn là Page_Load)
        protected void Page_Init(object sender, EventArgs e)
        {
            // Này của soft, cần nâng cấp hệ thống lại chỗ này
            //Libs.SettingHelper.InitGlobalSetting(Properties.Settings.Default.Properties); // load thông số cầu hình hệ thống lưu vào Libs để các nơi sử dụng được
            //Libs.SettingHelper.InitClassSetting(Classes.Default.Properties); // Load thông số cấu hình class để Core, Bll, DAL sử dụng

            SystemController.InitConnDB();
            if (!IsPostBack)
            {
                SystemController.TryLoginByToken(this); // tự động login nếu có token
            }
        }

        protected void Page_Load(object sender, EventArgs e)
        {
            if (!IsPostBack)
            {
                // xóa cache nếu admin cố tình gọi query đặc biệt
                if (Request.QueryString["rck"] != null && Request.QueryString["rck"] == "1")
                {
                    DCore.SessionUser objUser = Session[DCore.Globals.USER] as DCore.SessionUser;
                    if (objUser != null && objUser.IsAdministrator)
                    {
                        SystemService.SYS_SettingService.HaveNewData = true;
                    }
                }
            }
        }
    }
}

